import tokens from '../../docs/design/guide/tokens.json';

export type Level = 'low' | 'medium' | 'high' | 'unknown';

export const LEVELS: Level[] = ['low', 'medium', 'high', 'unknown'];

export const LEVEL_LABEL: Record<Level, string> = {
  low: 'Riesgo bajo',
  medium: 'Riesgo intermedio',
  high: 'Riesgo alto',
  unknown: 'Sin datos',
};

const FILLED_BARS: Record<Level, number> = { low: 1, medium: 2, high: 3, unknown: 0 };

/** [icon, Spanish label, Lucide name] for the icon grid. */
export const ICONS: [LucideIcon, string, string][] = [
  [Search, 'Buscar', 'search'],
  [MapPin, 'Ubicación', 'map-pin'],
  [SlidersHorizontal, 'Filtros', 'sliders-horizontal'],
  [ChevronDown, 'Desplegar', 'chevron-down'],
  [Info, 'Información', 'info'],
  [TriangleAlert, 'Advertencia', 'triangle-alert'],
  [CircleAlert, 'Error', 'circle-alert'],
  [CircleCheck, 'Confirmación', 'circle-check'],
  [LoaderCircle, 'Cargando', 'loader-circle'],
  [ExternalLink, 'Fuente externa', 'external-link'],
  [Share2, 'Compartir', 'share-2'],
  [X, 'Quitar', 'x'],
  [Check, 'Hecho', 'check'],
];

/** Three rising bars: the filled ones encode the level, so the tag reads without color. */
export function LevelGlyph({ level }: { level: Level }) {
  return (
    <svg className="lvl" viewBox="0 0 16 16" aria-hidden="true">
      {(
        [
          [1, 6],
          [6, 10],
          [11, 14],
        ] as const
      ).map(([x, h], i) =>
        level === 'unknown' ? (
          <rect
            key={x}
            x={x + 0.5}
            y={15 - h + 0.5}
            width={3}
            height={h - 1}
            rx={0.5}
            fill="none"
            stroke="currentColor"
            strokeDasharray="2 1.5"
          />
        ) : (
          <rect
            key={x}
            x={x}
            y={15 - h}
            width={4}
            height={h}
            rx={1}
            fill="currentColor"
            opacity={i < FILLED_BARS[level] ? undefined : 0.35}
          />
        ),
      )}
    </svg>
  );
}

type RiskTagProps = {
  /** Nivel calculado por la metodología (TASK-07); nunca se elige a mano. */
  level: Level;
  /** Grande: una sola vez, arriba de una ficha. */
  large?: boolean;
};

/** Nombra la categoría de riesgo de un territorio, entidad o contrato. */
export function RiskTag({ level, large = false }: RiskTagProps) {
  return (
    <span className={`el-tag el-tag-${level}${large ? ' el-tag-lg' : ''}`}>
      <LevelGlyph level={level} />
      {LEVEL_LABEL[level]}
    </span>
  );
}

/** es-CO number format: dot for thousands, comma for decimals, at most `decimals` decimals. */
export function formatNumber(value: number, decimals = 1): string {
  return new Intl.NumberFormat('es-CO', { maximumFractionDigits: decimals }).format(value);
}

export const FIXTURE = tokens.fixture;

// --- Map (fictional data; illustrative split, NOT agreed thresholds: see TASK-07) ---
export type Territory = (typeof territories)[number];
export const TERRITORIES: Territory[] = territories;

export function levelOf(t: Territory): Level {
  if (!t.analyzed) return 'unknown';
  const share = (100 * t.flagged) / t.analyzed;
  return share <= 12 ? 'low' : share <= 30 ? 'medium' : 'high';
}

const PATHS = [...mapSvg.matchAll(/<path data-region="([^"]+)"[^>]*?\sd="([^"]+)"/g)].map((m) => ({
  id: m[1] ?? '',
  d: m[2] ?? '',
}));

export function RiskMap({ selected, title }: { selected?: string; title: string }) {
  const levels = new Map(TERRITORIES.map((t) => [t.id, levelOf(t)]));
  // The selected territory is drawn last so its outline sits on top.
  const sorted = [...PATHS].sort((a, b) => Number(a.id === selected) - Number(b.id === selected));
  return (
    <svg className="el-map" viewBox="0 0 600 560" role="img" aria-labelledby="el-map-title">
      <title id="el-map-title">{title}</title>
      <defs>
        <pattern id="el-hatch" width="7" height="7" patternUnits="userSpaceOnUse">
          <rect width="7" height="7" className="el-hatch-bg" />
          <path d="M0 7L7 0" className="el-hatch-line" />
        </pattern>
      </defs>
      {sorted.map(({ id, d }) => (
        <path
          key={id}
          d={d}
          data-region={id}
          className={`el-fill-${levels.get(id) ?? 'unknown'}`}
          data-selected={id === selected ? 'true' : undefined}
        />
      ))}
    </svg>
  );
}

